"use client"

import * as React from "react"
import { cn } from "@/lib/utils"

export interface MagicCardProps extends React.HTMLAttributes<HTMLDivElement> {
  gradientSize?: number
  gradientColor?: string
  gradientOpacity?: number
  children?: React.ReactNode
}

export function MagicCard({
  children,
  className,
  gradientSize = 250,
  gradientColor = "rgba(14, 165, 233, 0.15)",
  gradientOpacity = 0.8,
  ...props
}: MagicCardProps) {
  const cardRef = React.useRef<HTMLDivElement>(null)
  const [mouseX, setMouseX] = React.useState(-gradientSize)
  const [mouseY, setMouseY] = React.useState(-gradientSize)

  const handleMouseMove = React.useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      if (cardRef.current) {
        const { left, top } = cardRef.current.getBoundingClientRect()
        setMouseX(e.clientX - left)
        setMouseY(e.clientY - top)
      }
    },
    []
  )

  const handleMouseLeave = React.useCallback(() => {
    setMouseX(-gradientSize)
    setMouseY(-gradientSize)
  }, [gradientSize])

  return (
    <div
      ref={cardRef}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      className={cn(
        "group relative flex flex-col overflow-hidden rounded-2xl bg-surface border border-border transition-all duration-300 hover:shadow-floating",
        className
      )}
      {...props}
    >
      <div
        className="pointer-events-none absolute -inset-px rounded-2xl opacity-0 transition-opacity duration-300 group-hover:opacity-100"
        style={{
          background: `radial-gradient(${gradientSize}px circle at ${mouseX}px ${mouseY}px, ${gradientColor}, transparent 100%)`,
          opacity: gradientOpacity,
        }}
      />
      <div className="relative z-10 flex flex-col flex-1">{children}</div>
    </div>
  )
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
